{
  "identity": {
    "name": "Ardent Industries Inc.",
    "location": "Nampa, Idaho",
    "claims": [
      {
        "statement": "The business operates under the corporate name Ardent Industries Inc.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "© 2026 Ardent Industries Inc. All rights reserved."
      },
      {
        "statement": "The company's facility is located on North Franklin Boulevard in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "1020 N. Franklin Blvd Suite 101 Nampa, ID 83687"
      },
      {
        "statement": "The business was initially founded in California before moving its operations to Idaho.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/about-us/",
        "quote": "Ardent Industries was established in California in 2014, relocating to Idaho in 2017."
      }
    ]
  },
  "industry": {
    "industry": "Precision Metal Fabrication and CNC Machining",
    "activities": [
      "Precision sheet metal fabrication",
      "CNC milling and turning",
      "Powder coating finishing services",
      "MIG and TIG welding",
      "E-commerce sales of fabricated metal accessories"
    ],
    "claims": [
      {
        "statement": "The company specializes in sheet metal fabrication, CNC machining, powder coating, and welding.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "We specialize in precision sheet metal fabrication, CNC machining, powder coating, and welding services in Nampa, Idaho, and the surrounding Treasure Valley."
      },
      {
        "statement": "The company produces components for industries such as semiconductor, robotics, and automotive aftermarket.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "Ardent Industries provides top-notch metal fabrication solutions for a wide range of industries, including but not limited to semiconductor, robotics, chemical processing, home furnishings, electronic components, and automotive aftermarket."
      },
      {
        "statement": "The business sells physical manufactured products directly through an online store.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/products/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ardentindustries.net/",
    "claims": [
      {
        "statement": "The official website presents Ardent Industries as a contract manufacturing and fabrication partner.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "Ardent Industries is your trusted partner in the world of manufactured products."
      },
      {
        "statement": "The company maintains active public social media links to Facebook, Instagram, and YouTube.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
