    {
      "product": "WordPress",
      "purpose": "Content management system for the public website",
      "evidence": {
        "statement": "The site loads assets from standard WordPress directories.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    },
    {
      "product": "WooCommerce",
      "purpose": "E-commerce platform for catalog browsing and cart checkout",
      "evidence": {
        "statement": "The website executes WooCommerce client scripts for cart and product handling.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/products/",
        "quote": null
      }
    },
    {
      "product": "Elementor / Elementor Pro",
      "purpose": "Website page builder and design framework",
      "evidence": {
        "statement": "The website utilizes Elementor plugin scripts for front-end rendering.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager",
      "purpose": "Website analytics tracking and tag deployment",
      "evidence": {
        "statement": "The site loads Google Tag Manager script gtag.js.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The contact page relies on an unassisted static contact form without file upload capabilities or automated RFQ specifications.",
      "label": "inference",
      "sourceUrl": "https://ardentindustries.net/contact-us/",
      "quote": null
    },
    {
      "statement": "The e-commerce store lists only two pre-fabricated products.",
      "label": "fact",
      "sourceUrl": "https://ardentindustries.net/products/",
      "quote": "Showing all 2 results"
    }
  ],
  "problems": [
    {
      "problem": "Ardent Industries is not an owner-led home-service contractor in HVAC, plumbing, or electrical trades.",
      "label": "fact",
      "basis": "The website explicitly defines the business as a CNC machining, sheet metal fabrication, powder coating, and welding manufacturing shop."
    },
    {
      "problem": "Custom manufacturing inquiries submitted through the generic web form may require manual intake and scoping.",
      "label": "hypothesis",
      "basis": "The contact form does not allow CAD drawing uploads or project parameter collection."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Manufacturing ERP / Estimating Software (e.g., Paperless Parts, JobBOSS2, or ProShop)",
      "addresses": "Automated CAD file intake, material nesting, job estimation, and work order tracking for machine shops",
      "alreadyOwned": false
    },
    {
      "solution": "WooCommerce with add-ons",
      "addresses": "Online merchandise order processing and payment collection",
      "alreadyOwned": true
    }
  ],
