    "rating": "not applicable",
    "explanation": "No AI delivery workflow is applicable as the prospect is disqualified based on industry sector."
  },
  "humanReview": [
    "Technical review of CAD models, material specifications, and machining tolerances must remain human-supervised in precision manufacturing."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Offering home-service automation templates to a custom metal fabricator risks severe process mismatch and wasted deployment resources."
    },
    {
      "type": "compliance",
      "description": "Manufacturing suppliers serving defense, aerospace, or semiconductor clients must comply with strict data handling and export control regulations (e.g., ITAR, CMMC) if external software touches engineering prints."
    }
  ],
